  function parkStoredPreconPdfs() {
    (state.projects || []).forEach(function (p) {
      const cycles = (p.tnc && p.tnc.preconCycles) || {};
      Object.keys(cycles).forEach(function (tag) {
        const c = cycles[tag];
        const src = c && (c.mergedPdf || c.packDataUrl);
        if (!src || c.mergedPdfId) return;
        rememberPreconPdf(c, src, tag).then(function () { saveState(); });
      });
    });
  }
  parkStoredPreconPdfs();
