  function emptyLouverRow(no) {
    return { id: uid(), no: no || 1, equipment: '', area: '', design: '', size: '600x100', p1: '', p2: '', p3: '', p4: '', p5: '', p6: '', avg: 0, cmh: 0 };
  }

  function emptySignRole() {
    return { name: '', designation: '', company: '', date: '', signature: '' };
  }

  function ensureLouverTable(t) {
    if (!t) return t;
    if (t.freeArea == null || t.freeArea === '') t.freeArea = '0.70';
    if (t.comments == null) t.comments = '';
    t.signOff = t.signOff || {};
    ['tested', 'witnessed', 'verified'].forEach(function (role) {
      t.signOff[role] = Object.assign(emptySignRole(), t.signOff[role] || {});
    });
    t.rows = (t.rows || []).slice(0, 10);
    t.rows.forEach(function (r, i) {
      if (r.p6 == null) r.p6 = '';
      r.no = i + 1;
    });
    return t;
  }

  function sampleDuct() {
    return {
      id: uid(),
      name: 'Duct Section 12 — AHU H1-2',
      project: 'WEPL ACMV',
      system: 'ACMV',
      subsystem: 'Air-Conditioning System',
      floor: 'Basement 1',
      room: 'Level 1, Zone A',
      equipment: 'AHU H1-2',
      section: 'Duct Section 12',
      pressureClass: 'B',
      testPa: 1000,
      drawing: 'ZK-C-MTPC-WE-ACMV-2300',
      measuredFactor: 0.291,
      remarks: 'Assessed at 1,000 Pa. Leakage within DW/144 Class B limit.',
      fittings: [
        { id: uid(), type: 'rect', w: 950, h: 500, length: 8000, w2: 0, h2: 0, angle: 90, radius: 500 },
        { id: uid(), type: 'reducer', w: 950, h: 500, length: 800, w2: 600, h2: 400, angle: 90, radius: 0 },
        { id: uid(), type: 'elbow', w: 600, h: 400, length: 0, w2: 0, h2: 0, angle: 90, radius: 600 },
        { id: uid(), type: 'rect', w: 600, h: 400, length: 3000, w2: 0, h2: 0, angle: 90, radius: 0 }
      ]
    };
  }

  function hydrateState(s) {
    s.uploads = s.uploads || [];
    s.libView = s.libView || {};
    s.libEdits = s.libEdits || {};
    s.calFolders = s.calFolders || [];
    s.calLibrary = s.calLibrary || {};
    ensureLists(s);
    (s.projects || []).forEach(function (p) {
      p.sheets = consolidateSheets(p.sheets || []);
      rehomeEquipment(p);
      p.sheets = consolidateSheets(p.sheets || []);
      ensureProjectTnc(p);
    });
    ensureMenhAssigned(s);
    (s.louverTables || []).forEach(ensureLouverTable);
    return s;
  }
  function loadState() {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const s = JSON.parse(raw);
        if (s && Array.isArray(s.projects)) return hydrateState(s);
      }
    } catch (e) { /* ignore */ }
    return defaultState();
  }
  function saveUiState() {
    try {
      localStorage.setItem(UI_KEY, JSON.stringify({
        view: view,
        selectedProjectId: selectedProjectId,
        selectedSheet: selectedSheet,
        selectedDuctId: selectedDuctId,
        selectedLouverId: selectedLouverId,
        tncTrackId: tncTrackId,
        tncStageId: tncStageId,
        tncEquipTag: tncEquipTag,
        tncSelectId: tncSelectId,
        tncOpenDocId: tncOpenDocId,
        tncClientCompanyQ: tncClientCompanyQ,
        tncRepoFolder: tncRepoFolder,
        tncRepoView: tncRepoView,
        tncRepoSearch: tncRepoSearch,
        tncExtractSearch: tncExtractSearch,
        tncCalFolder: tncCalFolder,
        tncCalSearch: tncCalSearch
      }));
    } catch (e) { /* ignore */ }
  }
  function restoreUiState() {
    try {
      const raw = localStorage.getItem(UI_KEY);
      if (!raw) return;
      const u = JSON.parse(raw);
      if (!u || typeof u !== 'object') return;
      const navIds = NAV.map(function (n) { return n.id; });
      if (u.view && navIds.indexOf(u.view) >= 0) view = u.view;
      if (u.selectedProjectId && (state.projects || []).some(function (p) { return p.id === u.selectedProjectId; })) {
        selectedProjectId = u.selectedProjectId;
      }
      if (typeof u.selectedSheet === 'number') selectedSheet = u.selectedSheet;
      if (u.selectedDuctId) selectedDuctId = u.selectedDuctId;
      if (u.selectedLouverId) selectedLouverId = u.selectedLouverId;
      if (u.tncTrackId) tncTrackId = u.tncTrackId;
      if (u.tncStageId) tncStageId = u.tncStageId;
      if (typeof u.tncEquipTag === 'string') tncEquipTag = u.tncEquipTag;
      if (u.tncSelectId) tncSelectId = u.tncSelectId;
      if (u.tncOpenDocId) tncOpenDocId = u.tncOpenDocId;
      if (u.tncClientCompanyQ) tncClientCompanyQ = u.tncClientCompanyQ;
      if (u.tncRepoFolder) tncRepoFolder = u.tncRepoFolder;
      if (u.tncRepoView === 'content' || u.tncRepoView === 'list' || u.tncRepoView === 'details') tncRepoView = u.tncRepoView;
      if (typeof u.tncRepoSearch === 'string') tncRepoSearch = u.tncRepoSearch;
      if (typeof u.tncExtractSearch === 'string') tncExtractSearch = u.tncExtractSearch;
      if (u.tncCalFolder) tncCalFolder = u.tncCalFolder;
      if (u.tncCalSearch) tncCalSearch = u.tncCalSearch;
    } catch (e) { /* ignore */ }
  }
  function saveState() {
    (state.projects || []).forEach(function (proj) {
      const cycles = (proj.tnc && proj.tnc.preconCycles) || {};
      Object.keys(cycles).forEach(function (tag) {
        const c = cycles[tag];
        if (!c) return;
        const src = c.mergedPdf || c.packDataUrl || '';
        if (src && src.length > 400000 && !c.mergedPdfId) {
          const id = uid();
          c.mergedPdfId = id;
          saveUpload({
            id: id,
            name: tag + '_Pre-Construction_Report.pdf',
            type: 'application/pdf',
            dataUrl: src,
            library: 'precon-merged',
            created: nowIso()
          });
        }
        if (c.mergedPdfId || (src && src.length > 400000)) {
          c.packDataUrl = '';
          c.mergedPdf = '';
        }
        (c.revisions || []).forEach(function (r) {
          if (r && r.dataUrl && r.dataUrl.length > 400000) r.dataUrl = '';
        });
      });
    });
    if (sharedPullDone) state.savedAt = nowIso();
    try {
      localStorage.setItem(KEY, JSON.stringify(state));
    } catch (e) { /* quota or private mode */ }
    saveUiState();
    scheduleSharedPost();
  }
  function sharedProjectCount(s) {
    return (s && s.projects && s.projects.length) || 0;
  }
  function localShouldLead(server) {
    const localN = sharedProjectCount(state);
    const serverN = sharedProjectCount(server);
    if (!serverN) return localN > 0;
    if (!localN) return false;
    const lt = state.savedAt || '';
    const st = (server && server.savedAt) || '';
    if (!lt && localN > serverN) return true;
    if (lt && (!st || lt > st)) return true;
    return false;
  }
  function adoptSharedState(s) {
    if (!s || !Array.isArray(s.projects) || !s.projects.length) return;
    state = hydrateState(s);
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
    if (!(state.projects || []).some(function (p) { return p.id === selectedProjectId; })) {
      selectedProjectId = state.projects[0] ? state.projects[0].id : null;
    }
  }
  function fetchSharedState() {
    return fetch('/api/state', { cache: 'no-store' }).then(function (r) {
      if (!r.ok) throw new Error('state');
      return r.json();
    });
  }
  function postSharedState() {
    if (!sharedPullDone) return Promise.resolve();
    if (!state.savedAt) state.savedAt = nowIso();
    return fetch('/api/state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(state)
    }).then(function (r) {
      if (r.status !== 409) return;
      return fetchSharedState().then(function (server) {
        adoptSharedState(server);
        const app = document.getElementById('app');
        if (app && !app.classList.contains('hidden')) {
          try { renderView(); } catch (e) { /* ignore */ }
        }
      });
    }).catch(function () { /* phone keeps working if this computer is offline */ });
  }
  function scheduleSharedPost() {
    if (!sharedPullDone) return;
    clearTimeout(sharedPostTimer);
    sharedPostTimer = setTimeout(function () { postSharedState(); }, 700);
  }
  function pullSharedState() {
    if (sharedPromise) return sharedPromise;
    sharedPromise = fetchSharedState().then(function (server) {
      if (localShouldLead(server)) {
        if (!state.savedAt) state.savedAt = nowIso();
        try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
        sharedPullDone = true;
        return postSharedState();
      }
      adoptSharedState(server);
      sharedPullDone = true;
    }).catch(function () {
      sharedPullDone = true;
    });
    return sharedPromise;
  }
  function logActivity(module, text) {
    state.activity.unshift({ id: uid(), module: module, text: text, at: nowIso() });
    state.activity = state.activity.slice(0, 40);
    saveState();
  }

  /* IndexedDB uploads */
  function idb() {
    return new Promise(function (resolve, reject) {
      const req = indexedDB.open('weplPortal', 1);
      req.onupgradeneeded = function () { req.result.createObjectStore('files', { keyPath: 'id' }); };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error); };
    });
  }
  function saveUpload(rec) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        const tx = db.transaction('files', 'readwrite');
        tx.objectStore('files').put(rec);
        tx.oncomplete = resolve;
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }
  function getUpload(id) {
    return idb().then(function (db) {
      return new Promise(function (resolve) {
        const tx = db.transaction('files', 'readonly');
        const q = tx.objectStore('files').get(id);
        q.onsuccess = function () { resolve(q.result); };
        q.onerror = function () { resolve(null); };
      });
    });
  }

  function svgIcon(name, cls) {
    return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="' + (cls || 'w-4 h-4') + '" aria-hidden="true">' + (ICONS[name] || ICONS.form) + '</svg>';
  }

  function renderNav() {
    const el = document.getElementById('sideNav');
    let html = '';
    let group = '';
    const u = currentUser();
    NAV.forEach(function (n) {
      if (authApi().canNav && !authApi().canNav(u, n.id)) return;
      if (n.group !== group) {
        group = n.group;
        html += '<p class="px-4 pt-4 pb-1 text-[10px] font-extrabold uppercase tracking-widest text-slate-500">' + esc(group) + '</p>';
      }
      const active = view === n.id;
      const btnClass = active
        ? 'flex items-center rounded-full transition-all duration-300 group relative text-left bg-gradient-to-r from-blue-900 to-blue-800 text-white shadow-lg hover:shadow-xl w-full px-4 py-3'
        : 'flex items-center rounded-full transition-all duration-300 group relative text-left w-full px-4 py-3 text-slate-300 hover:bg-white/10';
      const iconClass = 'nav-ico nav-ico-' + n.id + ' w-6 h-6 mr-4 flex-shrink-0';
      const titleClass = active
        ? 'text-sm font-semibold text-white transition-colors duration-300'
        : 'text-sm font-semibold text-slate-200 group-hover:text-white transition-colors duration-300';
      const descClass = active
        ? 'text-xs mt-1 text-blue-100 transition-colors duration-300'
        : 'text-xs mt-1 text-slate-500 group-hover:text-slate-300 transition-colors duration-300';
      html += '<button type="button" data-nav="' + n.id + '" class="nav-item ' + btnClass + '">' +
        svgIcon(n.icon, iconClass) +
        '<div class="flex-1 min-w-0">' +
        '<p class="' + titleClass + '">' + esc(n.label) + '</p>' +
        (n.desc ? '<p class="' + descClass + '">' + esc(n.desc) + '</p>' : '') +
        '</div></button>';
    });
    el.innerHTML = html;
    el.querySelectorAll('[data-nav]').forEach(function (btn) {
      btn.addEventListener('click', function () { navigate(btn.getAttribute('data-nav')); closeMobile(); });
    });
  }

  function navigate(id) {
    if (id === 'admin' && !isAdmin()) id = 'dashboard';
    if (view !== id) { libFilter = ''; libFilterFocus = false; }
    if (id === 'close-out') {
      view = 'project-tnc';
      tncTrackId = 'airflow';
      tncStageId = 'af-10';
    } else {
      view = id;
    }
    if (id === 'duct' && state.ductTests.length && !selectedDuctId) selectedDuctId = state.ductTests[0].id;
    if (id === 'louver' && state.louverTables.length && !selectedLouverId) selectedLouverId = state.louverTables[0].id;
    renderNav();
    renderView();
    closeSearch();
    saveUiState();
  }

  function isLg() {
    return window.matchMedia('(min-width: 1024px)').matches;
  }
  function setSidebarCollapsed(collapsed) {
    const app = document.getElementById('app');
    const btn = document.getElementById('btnCollapse');
    if (collapsed) app.classList.add('sidebar-collapsed');
    else app.classList.remove('sidebar-collapsed');
    if (btn) btn.title = collapsed ? 'Expand sidebar' : 'Collapse sidebar';
    try { localStorage.setItem('wepl-sidebar-collapsed', collapsed ? '1' : '0'); } catch (e) { }
  }
  function closeMobile() {
    if (isLg()) return;
    document.getElementById('sidebar').classList.add('-translate-x-full');
    document.getElementById('sidebarScrim').classList.add('hidden');
  }
  function openMobile() {
    document.getElementById('sidebar').classList.remove('-translate-x-full');
    document.getElementById('sidebarScrim').classList.remove('hidden');
  }

  function projectStats(p) {
    let total = 0, done = 0, bySys = { AHU: { t: 0, d: 0 }, FCU: { t: 0, d: 0 }, 'MV FAN': { t: 0, d: 0 } };
    (p.sheets || []).forEach(function (sh) {
      (sh.items || []).forEach(function (it) {
        total++;
        const sys = bySys[it.system] ? it.system : 'MV FAN';
        if (!bySys[sys]) bySys[sys] = { t: 0, d: 0 };
        bySys[sys].t++;
        if (Number(it.outstanding) === 0) { done++; bySys[sys].d++; }
      });
    });
    return { total: total, done: done, outstanding: total - done, pct: total ? Math.round(done / total * 1000) / 10 : 0, bySys: bySys };
  }

  function destroyCharts() {
    Object.keys(charts).forEach(function (k) { try { charts[k].destroy(); } catch (e) { } });
    charts = {};
  }

  function makeChart(id, cfg) {
    const ctx = document.getElementById(id);
    if (!ctx) return;
    if (charts[id]) charts[id].destroy();
    charts[id] = new Chart(ctx, cfg);
  }

  /* ===================== VIEWS ===================== */
  function renderView() {
    destroyCharts();
    disposeDuct();
    const root = document.getElementById('workspace');
    const map = {
      dashboard: renderDashboard,
      'project-tnc': renderProjectTnc,
      progress: renderProgress,
      'test-reports': function () { return renderLibrary('test-reports'); },
      mos: function () { return renderLibrary('mos'); },
      'pre-checklist': function () { return renderLibrary('pre-checklist'); },
      precon: function () { return renderLibrary('precon'); },
      'training-slides': function () { return renderLibrary('training-slides'); },
      room: renderRoom,
      duct: renderDuct,
      louver: renderLouver,
      psychrometric: renderPsychrometric,
      'duct-sizing': renderDuctSizing,
      'grille-sizing': renderGrilleSizing,
      'louvre-sizing': renderLouvreSizing,
      issues: renderIssues,
      admin: renderAdmin
    };
    const isLib = view === 'test-reports' || view === 'mos' || view === 'pre-checklist' || view === 'precon' || view === 'training-slides';
    const isProgress = view === 'progress' || view === 'project-tnc';
    const keepPlace = tncKeepPlace;
    try { closeGridCombos(); } catch (e) { /* ignore */ }
    try { closeMeasDds(); } catch (e) { /* ignore */ }
    const enterCls = keepPlace ? '' : 'workspace-enter ';
    const widthCls = 'w-full max-w-none min-w-0 ';
    if (isLib || isProgress) {
      root.classList.add('overflow-hidden');
      root.classList.remove('overflow-y-auto');
      root.innerHTML = '<div class="' + enterCls + widthCls + 'h-full min-h-0 flex flex-col">' + map[view]() + '</div>';
    } else {
      root.classList.add('overflow-y-auto');
      root.classList.remove('overflow-hidden');
      root.innerHTML = '<div class="' + enterCls + widthCls + '">' + (map[view] || renderDashboard)() + '</div>';
    }
    bindView();
    saveUiState();
    if (keepPlace) {
      tncKeepPlace = null;
      function pin() {
        const el = document.getElementById('tncStageScroll');
        if (el && keepPlace.top != null) el.scrollTop = keepPlace.top;
        if (keepPlace.win) window.scrollTo(0, keepPlace.win);
        if (keepPlace.focusRk) {
          const sel = document.querySelector('select[data-rk="' + keepPlace.focusRk + '"][data-unit-toggle="1"]')
            || document.querySelector('select[data-tnc-rep][data-rk="' + keepPlace.focusRk + '"]');
          if (sel) {
            try { sel.focus({ preventScroll: true }); } catch (e) { /* ignore */ }
          }
        }
        if (keepPlace.openComboRk) {
          const comboInp = document.querySelector('input[data-tnc-rep][data-rk="' + keepPlace.openComboRk + '"]');
          const wrap = comboInp && comboInp.closest('.od-combo');
          if (wrap) openGridCombo(wrap, true);
        }
      }
      pin();
      requestAnimationFrame(function () {
        pin();
        requestAnimationFrame(pin);
      });
    }
  }

