    const allProjects = visibleProjects();
    const filterId = dashProjectFilter;
    const filterOk = filterId && allProjects.some(function (p) { return p.id === filterId; });
    const viewProjects = filterOk ? allProjects.filter(function (p) { return p.id === filterId; }) : allProjects;
    const filterProject = viewProjects[0] || null;
    const totals = viewProjects.reduce(function (a, p) {
      const s = projectStats(p);
      a.total += s.total; a.done += s.done; a.out += s.outstanding; return a;
    }, { total: 0, done: 0, out: 0 });
    const pct = totals.total ? Math.round(totals.done / totals.total * 100) : 0;
    const u = currentUser();
    const greetName = String((u && u.name) || '').replace(/\s+/g, ' ').trim() || 'there';
    const cards = [
      { t: 'Projects', v: viewProjects.length, s: filterOk ? esc(filterProject.name) : 'Progress reports', ico: 'building', tone: 'projects' },
      { t: 'Equipment tracked', v: totals.total, s: pct + '% complete', ico: 'activity', tone: 'equip' },
      { t: 'Outstanding T&C', v: totals.out, s: totals.done + ' completed', ico: 'clock', tone: 'out' },
      { t: 'Test report forms', v: (CAT.testReports || []).length, s: 'Preview & print ready', ico: 'form', tone: 'forms' }
    ];
