        html += '<p class="text-xs text-slate-600 mb-1"><strong>R' + esc(h.revision || '') + '</strong> · ' + esc(h.action || '') + (h.comment ? ' — ' + esc(h.comment) : '') + ' <span class="text-slate-400">' + esc(h.by || '') + ' · ' + fmtDate(h.at) + '</span></p>';
