        const pg = Number(b.getAttribute('data-pg'));
        if (!isFinite(pg) || pg === Number(doc.gridPage || 0)) return;
        const scroller = document.getElementById('tncStageScroll');
        tncKeepPlace = {
          top: scroller ? scroller.scrollTop : 0,
          win: window.scrollY || document.documentElement.scrollTop || 0
        };
