        const rf = (tncData().reportFields || {})[(tpl && tpl.id) || doc.templateId];
        if (!rf || !rf.grid || !airGridUsesManagedPages(rf)) return;
        const maxPages = reportGridMaxPages(rf);
        let filled = 0;
        (doc.gridRows || []).forEach(function (row, i) {
          if (gridRowHasData(row)) filled = i + 1;
        });
        const vavPick = reportGridCols(rf.grid).some(function (c) { return c.vavPick; });
        const csv = (vavPick && p) ? vavCsvTags(p).length : 0;
        const cur = airGridManagedPageCount(doc, rf, filled, csv);
        if (cur >= maxPages) {
          alert('Maximum of ' + maxPages + ' pages reached for this form.');
          return;
        }
        doc.gridPageCount = cur + 1;
        ensureAirGridRows(p, doc, rf);
        doc.gridPage = doc.gridPageCount - 1;
        const scroller = document.getElementById('tncStageScroll');
        tncKeepPlace = {
          top: scroller ? scroller.scrollTop : 0,
          win: window.scrollY || document.documentElement.scrollTop || 0
        };
