      function saveSign() {
        const doc = findTncDoc(p, inp.getAttribute('data-tnc-sign')) || findCalCert(p, inp.getAttribute('data-tnc-sign'));
        if (!doc) return;
        doc.signOff = doc.signOff || emptyTncSignOff();
        const role = inp.getAttribute('data-role');
        const sf = inp.getAttribute('data-sf');
        doc.signOff[role] = doc.signOff[role] || emptyTncParty(role);
        if (role === 'tested' && (sf === 'name' || sf === 'designation')) {
          const card = inp.closest('.tnc-sign-card');
          const nameEl = card && card.querySelector('[data-sf="name"]');
          const desEl = card && card.querySelector('[data-sf="designation"]');
          const pair = pairTestedSign(sf, inp.value, nameEl ? nameEl.value : doc.signOff.tested.name);
          doc.signOff.tested.name = pair.name;
          doc.signOff.tested.designation = pair.designation;
          if (nameEl) { nameEl.value = pair.name; syncSelectPlaceholder(nameEl); }
          if (desEl) { desEl.value = pair.designation; syncSelectPlaceholder(desEl); }
          persistSharedReportUnitStore(p, doc);
          if (doc.trackId === 'precon') syncPreconSelectComplete(doc);
          saveState();
          return;
        }
        doc.signOff[role][sf] = inp.value;
        persistSharedReportUnitStore(p, doc);
        if (doc.trackId === 'precon' && role === 'tested') syncPreconSelectComplete(doc);
        saveState();
      }
      inp.addEventListener('change', function () {
        syncSelectPlaceholder(inp);
        saveSign();
      });
      const role = inp.getAttribute('data-role');
      const sf = inp.getAttribute('data-sf');
      if (role !== 'tested' && (sf === 'name' || sf === 'designation')) inp.addEventListener('input', saveSign);
