        if (doc.trackId === 'precon' && !preconCan().editStage1) return;
        syncOpenReportFromDom(doc);
        flushTncSignPadsToDoc(doc);
        if (!doc.signOff.tested.name) { alert('Enter Tested by name and e-signature before marking complete.'); return; }
        const tpl = tncMergeDocTemplate(doc) || tncTemplate('calibration', doc.templateId);
        if (tpl && tpl.kind === 'precon' && !preconChecklistReady(doc)) return;
