      const reason = ((document.getElementById('tncSkipReason') || {}).value || '').trim();
      if (!reason) { alert('Enter a reason for skipping this page.'); return; }
      p.tnc.skipReasons[tncStageId] = { reason: reason, by: actorName(), at: nowIso() };
      tncStageDocs(p, tncTrackId, tncStageById(tncTrackById(tncTrackId), tncStageId)).forEach(function (d) { d.skipped = true; });
      markStageSaved(p, tncStageId);
