    const searchForm = document.getElementById('btnTncSearchForm');
    if (searchForm) searchForm.onclick = function () {
      const inp = document.getElementById('tncFormPickSearch');
      const wrap = document.getElementById('tncFormDd');
      const q = String((inp && inp.value) || '').trim().toLowerCase();
      const items = Array.from(document.querySelectorAll('#tncFormDd .tnc-form-dd-item'));
      const matches = items.filter(function (el) {
        const hay = el.getAttribute('data-hay') || '';
        return !q || hay.indexOf(q) >= 0;
      });
      const exact = matches.find(function (el) {
        return String(el.textContent || '').trim().toLowerCase() === q;
      });
      const hit = exact || (matches.length === 1 ? matches[0] : null);
      if (hit) {
        tncSelectId = hit.getAttribute('data-id') || '';
        if (tncSelectId) tncOpenDocId = tncSelectId;
        renderView();
        return;
      }
      if (wrap && inp) {
        wrap.classList.add('is-open');
        inp.focus();
        inp.dispatchEvent(new Event('input', { bubbles: true }));
        return;
      }
      tncSelectId = (document.getElementById('tncFormPick') || {}).value || '';
      if (tncSelectId) tncOpenDocId = tncSelectId;
      renderView();
    };
