        p.tnc.uploads[stage.id] = p.tnc.uploads[stage.id] || [];
        const row = findRow(rowId);
        if (row && row.uploadId) {
          p.tnc.uploads[stage.id] = p.tnc.uploads[stage.id].filter(function (u) { return u.id !== row.uploadId; });
        }
        p.tnc.uploads[stage.id].push({ id: rec.id, name: rec.name, type: rec.type });
