    const readOnly = forcedLock;
    const inspTools = !readOnly && !!(opts.inspTools || opts.witnessTools || opts.verifyTools || (stageNow && (stageNow.kind === 'finalinsp' || stageNow.kind === 'witness' || stageNow.kind === 'verify')));
    const witnessTools = !readOnly && !!(opts.witnessTools || opts.verifyTools || (stageNow && (stageNow.kind === 'witness' || stageNow.kind === 'verify')));
    const clientTools = !readOnly && !inspTools && !!(stageNow && stageNow.kind === 'clientforms');
