    const redoBtn = host.querySelector('[data-pdf-redo]');
    if (redoBtn) redoBtn.onclick = function (e) { e.preventDefault(); redoLast(); };
    const zin = host.querySelector('[data-pdf-zin]');
    const zout = host.querySelector('[data-pdf-zout]');
    const fitw = host.querySelector('[data-pdf-fitw]');
    const fitp = host.querySelector('[data-pdf-fitp]');
    const fsBtn = host.querySelector('[data-pdf-fs]');
    if (zin) zin.onclick = function () { setView('custom', (viewMode === 'custom' ? zoom : 1) / 1.2); };
    if (zout) zout.onclick = function () { setView('custom', (viewMode === 'custom' ? zoom : 1) * 1.2); };
    if (fitw) fitw.onclick = function () { setView('fitWidth', 1); };
